// Package geo is the reference list of countries, their first-level divisions (regions: states, provinces, counties) and the places under each region
// (districts: second-level divisions and towns of 15000 people or more), as GeoNames publishes them. The console offers them wherever it asks for an
// address; an address still stores the country code and the region and city as text, so nothing here decides what an address may say.
//
// The data is generated by cmd/geoimport from the GeoNames dumps and embedded (data/geonames.json.gz), so a build and the tests need no network.
// GeoNames data is licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/); see docs/geo-data.md for the attribution.
package geo

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strings"
	"sync"
)

// Attribution is the credit the licence asks for, sent with every answer that carries the data.
const Attribution = "Data from GeoNames (https://www.geonames.org), licensed under CC BY 4.0"

// Country is one country (ISO 3166-1, plus XK for Kosovo, as GeoNames lists it). The name is English; the console shows the name in the page's language.
type Country struct {
	ISO2      string `json:"iso2"`
	ISO3      string `json:"iso3"`
	Name      string `json:"name"`
	Continent string `json:"continent"`
	GeonameID int    `json:"geoname_id"`
}

// Region is a first-level division of a country. ID is GeoNames' admin1 code ("TR.34"); Code is the part after the country ("34").
type Region struct {
	ID        string `json:"id"`
	Code      string `json:"code"`
	Name      string `json:"name"`
	ASCIIName string `json:"ascii_name"`
	GeonameID int    `json:"geoname_id"`
}

// Kinds of district.
const (
	KindAdmin2 = "admin2" // a second-level division (a district, county or municipality)
	KindCity   = "city"   // a populated place of 15000 people or more that no division of the same name covers
)

// District is a place under a region: a second-level division (ID is its admin2 code, "TR.34.1234") or a town (ID is its GeoNames id).
type District struct {
	ID        string `json:"id"`
	Name      string `json:"name"`
	ASCIIName string `json:"ascii_name"`
	Kind      string `json:"kind"`
}

// Dataset is the whole list as the generated file holds it.
type Dataset struct {
	// Version names the GeoNames export the file was made from ("geonames-2026-10-26").
	Version   string                `json:"version"`
	Countries []Country             `json:"countries"`
	Regions   map[string][]Region   `json:"regions"`   // by country ISO2
	Districts map[string][]District `json:"districts"` // by region id
}

//go:embed data/geonames.json.gz
var embedded []byte

var (
	once    sync.Once
	loaded  *Dataset
	loadErr error
)

// Default is the embedded dataset, decoded on first use.
func Default() (*Dataset, error) {
	once.Do(func() { loaded, loadErr = Decode(bytes.NewReader(embedded)) })
	return loaded, loadErr
}

// Decode reads a dataset written by Encode.
func Decode(r io.Reader) (*Dataset, error) {
	zr, err := gzip.NewReader(r)
	if err != nil {
		return nil, fmt.Errorf("geo: open data: %w", err)
	}
	defer func() { _ = zr.Close() }()
	var d Dataset
	if err := json.NewDecoder(zr).Decode(&d); err != nil {
		return nil, fmt.Errorf("geo: decode data: %w", err)
	}
	return &d, nil
}

// Encode writes the dataset as gzipped JSON. The output depends only on the dataset (no time stamp in the gzip header, map keys sorted), so importing the
// same export twice gives the same file.
func Encode(w io.Writer, d *Dataset) error {
	zw, err := gzip.NewWriterLevel(w, gzip.BestCompression)
	if err != nil {
		return err
	}
	if err := json.NewEncoder(zw).Encode(d); err != nil {
		return err
	}
	return zw.Close()
}

// Country returns the country with the ISO2 code (any case).
func (d *Dataset) Country(iso2 string) (Country, bool) {
	iso2 = strings.ToUpper(iso2)
	i := sort.Search(len(d.Countries), func(i int) bool { return d.Countries[i].ISO2 >= iso2 })
	if i < len(d.Countries) && d.Countries[i].ISO2 == iso2 {
		return d.Countries[i], true
	}
	return Country{}, false
}

// RegionsOf returns the regions of a country, sorted by name, and whether the country exists. A country may exist with no regions.
func (d *Dataset) RegionsOf(iso2 string) ([]Region, bool) {
	c, ok := d.Country(iso2)
	if !ok {
		return nil, false
	}
	return d.Regions[c.ISO2], true
}

// DistrictsOf returns the districts of a region, sorted by name, and whether the region exists. A region may exist with no districts.
func (d *Dataset) DistrictsOf(regionID string) ([]District, bool) {
	country, _, found := strings.Cut(regionID, ".")
	if !found {
		return nil, false
	}
	regions, ok := d.RegionsOf(country)
	if !ok {
		return nil, false
	}
	for _, r := range regions {
		if strings.EqualFold(r.ID, regionID) {
			return d.Districts[r.ID], true
		}
	}
	return nil, false
}
